//! A real PDF, read through PDFium: the fragments of a two-column bibliography.
//!
//! The sample corpus this repository is measured against turns out to hold **no** two-column page
//! at all (0 of its 298 pages show a column gutter), so the column-split path would otherwise be
//! exercised only by hand-built pages. This fixture is generated by `scripts/make-fixtures.py` and
//! read through the same backend the application uses: entry 2 starts at the foot of the left
//! column and ends at the head of the right one, so it must come back as two fragments, one on
//! each side of the gutter the page really shows.

use lyra_reader_core::{DocumentBackend, PageIndex};
use lyra_reader_pdfium::PdfiumBackend;
use lyra_reader_text::{ReferenceEntry, find_references, lines_from, tables::column_gutter};
mod common;

/// The fixture page's gutter, or `None` when PDFium is unavailable in this build.
fn fixture_gutter() -> Option<(PdfiumBackend, f64)> {
    if !lyra_reader_pdfium::is_available() {
        eprintln!("skipping: no PDFium");
        return None;
    }
    let fixture = common::fixture("two-column-references.pdf");
    let backend = PdfiumBackend::open(&fixture, None).expect("open fixture");
    let page = backend.raw_text_page(PageIndex(0)).expect("extract text");
    let gutter = column_gutter(&lines_from(&page), None).expect("the fixture shows a gutter");
    Some((backend, gutter))
}

#[test]
fn an_entry_that_crosses_the_gutter_comes_back_as_two_fragments() {
    let Some((backend, gutter)) = fixture_gutter() else {
        return;
    };
    let page = backend.raw_text_page(PageIndex(0)).expect("extract text");
    let entries = find_references([(0u32, &page)], 100);
    assert_eq!(
        entries
            .iter()
            .map(|entry| entry.label.as_str())
            .collect::<Vec<_>>(),
        ["1", "2", "3", "4", "5", "6"],
        "{entries:?}"
    );

    let entry = |label: &str| -> ReferenceEntry {
        entries
            .iter()
            .find(|entry| entry.label == label)
            .unwrap_or_else(|| panic!("entry {label}"))
            .clone()
    };

    // Entry 2 is drawn in the left column and in the right one: two pieces, one per column, and
    // neither box reaches across the gutter.
    let split = entry("2");
    assert_eq!(split.fragments.len(), 2, "{:?}", split.fragments);
    assert!(
        split.text.contains("carry on to the right"),
        "{}",
        split.text
    );
    assert!(split.text.contains("It ends here"), "{}", split.text);
    let left = split.fragments[0];
    let right = split.fragments[1];
    assert_eq!(left.page, 0);
    assert_eq!(right.page, 0);
    assert_eq!(left.start, split.start);
    assert_eq!(left.end, right.start);
    assert!(left.rect.max_x() <= gutter, "{left:?} vs gutter {gutter}");
    assert!(
        right.rect.origin.x >= gutter,
        "{right:?} vs gutter {gutter}"
    );
    assert!(right.rect.origin.y > left.rect.origin.y, "{split:?}");

    // The entries that fit in one column are one fragment each, on their own side.
    let single = entry("1");
    assert_eq!(single.fragments.len(), 1, "{:?}", single.fragments);
    assert!(single.fragments[0].rect.max_x() <= gutter);
    let right_column = entry("3");
    assert_eq!(
        right_column.fragments.len(),
        1,
        "{:?}",
        right_column.fragments
    );
    assert!(right_column.fragments[0].rect.origin.x >= gutter);

    // The acceptance criterion, on a real page: no fragment box spans the gutter.
    for entry in &entries {
        for fragment in &entry.fragments {
            assert!(
                fragment.rect.max_x() <= gutter || fragment.rect.origin.x >= gutter,
                "{} crosses the gutter: {:?}",
                entry.label,
                fragment
            );
        }
    }
}
